INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "杨溥", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷270贞明五年条所见人物：杨溥。", "biography": null, "status": "draft", "id": "c9c313a8-8feb-5442-a006-67b9f78d476b"}, {"name": "李德诚", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258龙纪元年条所见人物：李德诚。", "biography": null, "status": "draft", "id": "59a78323-0271-515f-9eee-806a51a30252"}, {"name": "李昪", "aliases": ["徐知诰", "知诰"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：李昪。", "biography": null, "status": "draft", "id": "5a8b1ad8-1e2e-5318-ae39-1ab3a3e244f9"}, {"name": "李建勋", "aliases": ["李建勳"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：李建勋，节度副使、屡陈功业者。", "biography": null, "status": "draft", "id": "6b23676b-32be-5201-8ad3-171b7cc648e3"}, {"name": "杨檀", "aliases": ["楊檀", "杨光远", "楊光遠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：杨檀，冀州刺史、反对遣归者。", "biography": null, "status": "draft", "id": "54ec3b10-aece-5189-91a8-84a03c5691a3"}, {"name": "石敬瑭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：石敬瑭。", "biography": null, "status": "draft", "id": "bf42d98c-7477-5be1-a767-867fe26cf617"}, {"name": "杨承祚", "aliases": ["楊承祚"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "杨光远的儿子。938年五月被任命为左威卫将军，并与石敬瑭的女儿长安公主结婚。", "biography": null, "status": "draft", "id": "2af4e0bd-ddb5-5c72-b4f6-8e3394d31c7d"}, {"name": "长安公主（石敬瑭女）", "aliases": ["长安公主", "長安公主"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋皇帝石敬瑭的女儿，以长安公主为封号。938年五月与杨承祚结婚，个人姓名和生卒年此段未载。", "biography": null, "status": "draft", "id": "dc36c975-97c7-5d8a-8f3e-290bd1ace31e"}, {"name": "杨承信", "aliases": ["楊承信"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "杨光远的儿子。《资治通鉴》称他为次子，938年五月与杨承祚同获优厚任官，具体官名未载。", "biography": null, "status": "draft", "id": "70bde002-fc6d-5293-9fb1-214458b656a6"}, {"name": "王舆（吴光州刺史）", "aliases": ["王舆（吴）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王舆（吴光州刺史），传拯之叔父。", "biography": null, "status": "draft", "id": "5ed76298-da8c-53be-ab2f-7e4e6a65f6b4"}, {"name": "公孙圭", "aliases": ["公孫圭"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐官员。原任客省使，938年五月在杨溥迁居丹杨宫的安排中被任命为监军使。", "biography": null, "status": "draft", "id": "35f4b4e6-b410-5a7a-b113-3d1df4168362"}, {"name": "马思让", "aliases": ["馬思讓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "徐诰的亲近吏员。938年五月被任命为丹杨宫使，参与杨溥迁居后的管理安排。", "biography": null, "status": "draft", "id": "c4631197-fb09-5088-9346-9e304a99e9b7"}, {"name": "宋齐丘", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化二年条所见人物：宋齐丘。", "biography": null, "status": "draft", "id": "313ec6c3-7027-5fef-8b5d-b79d259f9c8a"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "杨嗣（南唐留守判官）", "aliases": ["杨嗣", "楊嗣"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐留守判官。938年六月请求改姓羊，徐玠反对更改带有吴、杨名称或姓氏的做法，徐诰接受徐玠的意见。杨嗣并未在此段被记为已经改姓。", "biography": null, "status": "draft", "id": "5eef2819-996a-5bc1-be2a-6e3f5ce3968d"}, {"name": "徐玠", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化二年条所见人物：徐玠。", "biography": null, "status": "draft", "id": "70906153-ef05-55ab-b89f-58cf163dfda3"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

